function validate([nums, target, start]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 10000)) return 'Each value of nums is an integer from 1 to 10^4.';
  if (!Number.isInteger(start) || start < 0 || start >= nums.length) return 'start must be a valid index of nums.';
  if (!nums.includes(target)) return 'target must occur in nums.';
  return null;
}

