  for (let distance = 0; distance < nums.length; distance++) {
    const left = start - distance;
    const right = start + distance;
    if (left >= 0 && nums[left] === target) {
      return distance;
    }
    if (right < nums.length && nums[right] === target) {
      return distance;
    }
  }
  return -1;
}

