function generate(rand, size) {
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 10);
  const top = size === 'large' ? 10000 : 1 + Math.floor(rand() * 5);
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const start = Math.floor(rand() * n);
  let target = nums[Math.floor(rand() * n)];
  if (size === 'large' && rand() < 0.5) {
    // Put a fresh value at one far spot so the answer is a long walk away.
    const far = start < n / 2 ? n - 1 - Math.floor(rand() * 20) : Math.floor(rand() * 20);
    target = 1 + Math.floor(rand() * 10000);
    for (let i = 0; i < n; i++) if (nums[i] === target) nums[i] = target === 1 ? 2 : target - 1;
    nums[far] = target;
  }
  return [nums, target, start];
}
